            {values.map((v, i) => (
              <div key={i} className="flex-1 rounded-sm bg-brand/70" style={{ height: `${(v / max) * 100}%` }} />
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-3 rounded-lg bg-surface p-6 shadow-sm">
          <span className="text-sm text-ink-muted">Plan usage</span>
