        </div>

        <div className="flex flex-col gap-3 rounded-lg bg-surface p-6 shadow-sm md:col-span-3">
          <span className="text-sm text-ink-muted">Live activity</span>
          <LiveMap />
        </div>
      </main>
    </div>
  );
}

